/* eslint-disable @typescript-eslint/no-explicit-any */
import { ChevronDown, ChevronUp } from '@hexa-ui/icons';
import React, {
  forwardRef,
  HTMLProps,
  ReactNode,
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  useCallback,
} from 'react';
import { Value } from '@radix-ui/react-select';
import {
  StyledArrowDownContainer,
  StyledArrowUpContainer,
  StyledChevronDown,
  StyledErrorMessage,
  StyledLabel,
  StyledPopover,
  StyledScrollContainer,
  StyledSelect,
  StyledUl,
  StyledWrapper,
  StyledIconContainer,
  StyledValueContainer,
  StyledInfoIcon,
  StyledHint,
  StyledContent,
} from './Select.styles';
import { useOnClickOutside } from '../../hooks/useOnClickOutside/useOnClickOutside';

type VariantProps =
  | {
      multiple?: false;
      defaultValue?: string;
      value?: string;
      displayText?: never;
    }
  | {
      multiple: true;
      defaultValue?: Array<string>;
      value?: Array<string>;
      displayText?: string;
    };

export interface CommomProps {
  size?: 'small' | 'medium' | 'large';
  label?: string;
  icon?: ReactNode;
  shape?: 'square' | 'pill';
  hint?: string;
  error?: string;
  children?: ReactNode;
  onChange?: (value: any) => void;
  name?: string;
  disabled?: boolean;
  placeholder?: string;
  labelProps?: Omit<HTMLProps<HTMLLabelElement>, 'ref'>;
  width?: string | number;
  onBlur?: React.FocusEventHandler<HTMLDivElement>;
  id?: string;
}

export type SelectProps = CommomProps & VariantProps;

const SelectRoot = forwardRef(
  (
    {
      children,
      hint,
      error,
      icon,
      label,
      onChange,
      multiple = false,
      displayText = 'items selected',
      shape = 'square',
      size = 'large',
      defaultValue,
      name,
      value,
      disabled,
      placeholder = 'Select a value',
      labelProps,
      width = '100%',
      onBlur,
      id,
      ...restProps
    }: SelectProps,
    forwardedRef: React.ForwardedRef<HTMLButtonElement>
  ): JSX.Element => {
    const innerRef = useRef<HTMLButtonElement>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [valueState, setValueState] = useState<any>('');
    const [selectedLabel, setSelectedLabel] = useState<string>('');

    useEffect(() => {
      if (multiple) {
        const initialMultipleState = value ?? defaultValue;
        setValueState(initialMultipleState ?? []);
      }
    }, [defaultValue, multiple, value]);

    const hideSelect = useCallback((event) => {
      // Prevent popover not opening on mobile devices
      if (!innerRef.current || innerRef.current.contains(event.target)) {
        return;
      }

      setIsOpen(false);
    }, []);

    useOnClickOutside(containerRef, hideSelect);

    if (!multiple) {
      if (Array.isArray(defaultValue))
        throw new Error(
          'Expect a defaultValue with type of "string", but got a "string[]" instead.'
        );
      if (Array.isArray(value))
        throw new Error('Expect a value with type of "string", but got a "string[]" instead.');
    }

    if (multiple) {
      if (defaultValue && !Array.isArray(defaultValue))
        throw new Error(
          'Expect a defaultValue with type of "string[]", but got a "string" instead.'
        );

      if (value && !Array.isArray(value))
        throw new Error('Expect a value with type of "string[]", but got a "string" instead.');
    }

    function handleChange(changeValue: string) {
      handleOnChangeCallback(changeValue);

      if (multiple) {
        if (valueState.includes(changeValue)) {
          return setValueState((state: string[]) =>
            state.filter((item: string) => item !== changeValue)
          );
        }

        return setValueState((state: string | string[]) => [...state, changeValue]);
      }
      setIsOpen(false);
      return setValueState(changeValue);
    }

    function handleOnChangeCallback(changedValue: string) {
      if (onChange && typeof onChange === 'function') {
        if (multiple) {
          if (valueState.includes(changedValue) && Array.isArray(valueState)) {
            return onChange(valueState.filter((item: string) => item !== changedValue));
          }
          return onChange([...valueState, changedValue]);
        }

        return onChange(changedValue);
      }

      return null;
    }

    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLButtonElement);

    const renderValue = () => {
      if (valueState.length === 1) {
        return selectedLabel;
      }

      if (valueState.length === 0) {
        return placeholder;
      }

      return `${valueState.length} ${displayText}`;
    };

    const onMultipleChange = (selectedText: string) => setSelectedLabel(selectedText);

    const mappedChildren = React.Children.map(
      children as React.ReactElement[],
      (child: React.ReactElement) =>
        React.cloneElement(child, {
          ...child.props,
          multiple,
          selectedValues: valueState,
          disabled: disabled || child.props.disabled,
          onMultipleChange,
        })
    );

    return (
      <StyledWrapper
        onValueChange={(changedValue) => handleChange(changedValue)}
        onOpenChange={(open) => setIsOpen(multiple ? true : open)}
        open={isOpen}
        css={{ width }}
        name={name}
        defaultValue={defaultValue as string}
        // eslint-disable-next-line @typescript-eslint/ban-ts-comment
        // @ts-ignore
        value={multiple ? null : value}
      >
        {label && (
          <StyledLabel disabled={disabled} error={Boolean(error)} {...labelProps}>
            {label}
          </StyledLabel>
        )}
        {hint && <StyledHint>{hint}</StyledHint>}
        {error && (
          <StyledErrorMessage>
            <StyledInfoIcon size="tiny" />
            {error}
          </StyledErrorMessage>
        )}
        <StyledSelect
          size={size}
          error={Boolean(error)}
          disabled={disabled}
          shape={shape}
          ref={innerRef}
          name={name}
          data-testid={(restProps as Record<string, unknown>)['data-testid']}
          id={id}
          css={{ width }}
        >
          {icon && <StyledIconContainer>{icon}</StyledIconContainer>}
          <StyledValueContainer>
            {multiple ? (
              <Value placeholder={placeholder}>{renderValue()}</Value>
            ) : (
              <Value placeholder={placeholder} />
            )}
          </StyledValueContainer>
          <StyledChevronDown size="medium" />
        </StyledSelect>
        <StyledPopover onBlur={onBlur}>
          <StyledContent
            ref={(ref: HTMLDivElement) => {
              containerRef.current = ref;
              if (ref) {
                ref.addEventListener('touchend', (e) => e.preventDefault());
              }
            }}
            position="popper"
          >
            <StyledArrowUpContainer>
              <ChevronUp size="medium" />
            </StyledArrowUpContainer>
            <StyledScrollContainer>
              <StyledUl>{mappedChildren}</StyledUl>
            </StyledScrollContainer>
            <StyledArrowDownContainer>
              <ChevronDown size="medium" />
            </StyledArrowDownContainer>
          </StyledContent>
        </StyledPopover>
      </StyledWrapper>
    );
  }
);

export default SelectRoot;
